import { Data } from "effect"

export type UploadState = Data.TaggedEnum<{
  Queued: { readonly fileName: string }
  Uploading: { readonly fileName: string; readonly bytesSent: number }
  Complete: { readonly downloadUrl: string }
  Rejected: { readonly message: string }
}>

export const UploadState = Data.taggedEnum<UploadState>()

export const describeUpload = (state: UploadState): string => {
  switch (state._tag) {
    case "Queued":
      return `Waiting to upload ${state.fileName}`
    case "Uploading":
      return `${state.fileName}: ${state.bytesSent} bytes sent`
    case "Complete":
      return `Available at ${state.downloadUrl}`
    case "Rejected":
      return `Upload rejected: ${state.message}`
  }
}

export const canRetryUpload = (state: UploadState): boolean =>
  state._tag === "Rejected"
